   8| /// retry：出错时重新订阅源流，最多重试 times 次
   9| pub fn[T, E] Observable::retry(self : Observable[T, E], times : Int) -> Observable[T, E] {
  10|   let source_fn = self.subscribe_fn
  11|   let subscribe_fn : (Observer[T, E]) -> Subscription = fn(downstream : Observer[T, E]) {
  12|     let next = downstream.next
  13|     let error = downstream.error
  14|     let complete = downstream.complete
  15|     let attempts = Ref::Ref(0)
  16|     let done = Ref::Ref(false)
  17|     let try_ref = Ref::Ref(fn() {})
  18|     let try_subscribe : () -> Unit = fn() {
  19|       if done.val {
  20|         return
  21|       }
  22|       let _ = source_fn({
  23|         next: next,
  24|         error: fn(e : E) {
  25|           if attempts.val < times {
  26|             attempts.val = attempts.val + 1
  27|             try_ref.val()
  28|           } else {
  29|             done.val = true
  30|             error(e)
  31|           }
  32|         },
  33|         complete: fn() {
  34|           if !done.val {
  35|             done.val = true
  36|             complete()
  37|           }
  38|         },
  39|       })
  40|     }
  41|     try_ref.val = try_subscribe
  42|     try_subscribe()
  43|   }
  44|   Observable::new(subscribe_fn)
  45| }
  46| 
  47| /// retry_indefinitely：出错时无限重试
  48| pub fn[T, E] Observable::retry_indefinitely(self : Observable[T, E]) -> Observable[T, E] {
  49|   let source_fn = self.subscribe_fn
  50|   let subscribe_fn : (Observer[T, E]) -> Subscription = fn(downstream : Observer[T, E]) {
  51|     let next = downstream.next
  52|     let error = downstream.error
  53|     let complete = downstream.complete
  54|     let done = Ref::Ref(false)
  55|     let try_ref = Ref::Ref(fn() {})
  56|     let try_subscribe : () -> Unit = fn() {
  57|       if done.val {
  58|         return
  59|       }
  60|       let _ = source_fn({
  61|         next: next,
  62|         error: fn(_e : E) { try_ref.val() },
  63|         complete: fn() {
  64|           if !done.val {
  65|             done.val = true
  66|             complete()
  67|           }
  68|         },
  69|       })
  70|     }
  71|     try_ref.val = try_subscribe
  72|     try_subscribe()
  73|   }
  74|   Observable::new(subscribe_fn)
  75| }
