  77| /// retry_when：出错时按条件决定是否重试
  78| pub fn[T, E] Observable::retry_when(
  79|   self : Observable[T, E],
  80|   should_retry : (E) -> Bool,
  81| ) -> Observable[T, E] {
  82|   let source_fn = self.subscribe_fn
  83|   let subscribe_fn : (Observer[T, E]) -> Subscription = fn(downstream : Observer[T, E]) {
  84|     let next = downstream.next
  85|     let error = downstream.error
  86|     let complete = downstream.complete
  87|     let done = Ref::Ref(false)
  88|     let try_ref = Ref::Ref(fn() {})
  89|     let try_subscribe : () -> Unit = fn() {
  90|       if done.val {
  91|         return
  92|       }
  93|       let _ = source_fn({
  94|         next: next,
  95|         error: fn(e : E) {
  96|           if should_retry(e) {
  97|             try_ref.val()
  98|           } else {
  99|             done.val = true
 100|             error(e)
 101|           }
 102|         },
 103|         complete: fn() {
 104|           if !done.val {
 105|             done.val = true
 106|             complete()
 107|           }
 108|         },
 109|       })
 110|     }
 111|     try_ref.val = try_subscribe
 112|     try_subscribe()
 113|   }
