 125| /// retry_with_backoff_on：指定虚拟时钟的指数退避重试
 126| pub fn[T, E] Observable::retry_with_backoff_on(
 127|   self : Observable[T, E],
 128|   clock : Clock,
 129|   initial_ms : Int64,
 130| ) -> Observable[T, E] {
 131|   let source_fn = self.subscribe_fn
 132|   let subscribe_fn : (Observer[T, E]) -> Subscription = fn(downstream : Observer[T, E]) {
 133|     let next = downstream.next
 134|     let error = downstream.error
 135|     let complete = downstream.complete
 136|     let done = Ref::Ref(false)
 137|     let attempts = Ref::Ref(0)
 138|     let try_ref = Ref::Ref(fn() {})
 139|     let try_subscribe : () -> Unit = fn() {
 140|       if done.val {
 141|         return
 142|       }
 143|       let _ = source_fn({
 144|         next: next,
 145|         error: fn(_e : E) {
 146|           let shift = 1 << attempts.val
 147|           let delay = initial_ms * Int64::from_int(shift)
 148|           attempts.val = attempts.val + 1
 149|           clock.set_timer(delay, fn() { try_ref.val() })
 150|         },
 151|         complete: fn() {
 152|           if !done.val {
 153|             done.val = true
 154|             complete()
 155|           }
 156|         },
 157|       })
 158|     }
 159|     try_ref.val = try_subscribe
 160|     try_subscribe()
 161|   }
 162|   Observable::new(subscribe_fn)
 163| }
