/// all：所有值都满足谓词时发 true（与 every 等价，Rx-Rust 命名）
pub fn[T, E] Observable::all(
  self : Observable[T, E],
  predicate : (T) -> Bool,
) -> Observable[Bool, E] {
  self.every(predicate)
